import {getItem, removeItem, setItem} from '@github-ui/safe-storage/session-storage'
import {useAnalytics} from '@github-ui/use-analytics'
import {useDebounce} from '@github-ui/use-debounce'
import {Banner} from '@primer/react/experimental'
import {useCallback, useState} from 'react'

export function UnsavedChangesBanner({
  discardContent,
  restoreContent,
}: {
  discardContent: () => void
  restoreContent: () => void
}) {
  return (
    <Banner
      title="Unsaved changes"
      description="You have unsaved changes on this file that can be restored."
      variant="info"
      onDismiss={discardContent}
      primaryAction={<Banner.PrimaryAction onClick={restoreContent}>Restore</Banner.PrimaryAction>}
      secondaryAction={<Banner.SecondaryAction onClick={discardContent}>Discard</Banner.SecondaryAction>}
      hideTitle
      className="mb-3"
    />
  )
}

type DiscardSource = 'save' | 'cancel' | 'banner'

export function useUnsavedContent(cacheKey: string) {
  const [failedToPersist, setFailedToPersist] = useState(false)
  const [hasUnsavedContent, setHasUnsavedContent] = useState(() => !!getItem(cacheKey))
  const {sendAnalyticsEvent} = useAnalytics()

  const restoreContent = useCallback(() => {
    setHasUnsavedContent(false)
    const content = getItem(cacheKey)

    if (content) {
      sendAnalyticsEvent('code_view.unsaved_changes.restored')
    } else {
      sendAnalyticsEvent('code_view.unsaved_changes.restored_no_content')
    }

    return content
  }, [cacheKey, sendAnalyticsEvent])

  const debouncedPersistContent = useDebounce((content: string) => {
    if (failedToPersist) return

    try {
      setItem(cacheKey, content)
    } catch {
      setFailedToPersist(true)
      sendAnalyticsEvent('code_view.unsaved_changes.persist_failure')
    }
  }, 1000)

  const discardContent = useCallback(
    (source: DiscardSource) => {
      setHasUnsavedContent(false)
      removeItem(cacheKey)

      if (source === 'banner') {
        sendAnalyticsEvent('code_view.unsaved_changes.discarded')
      }
    },
    [cacheKey, sendAnalyticsEvent],
  )

  return {
    hasUnsavedContent,
    restoreContent,
    discardContent,
    persistContent: debouncedPersistContent,
  }
}

try{ UnsavedChangesBanner.displayName ||= 'UnsavedChangesBanner' } catch {}